#!/usr/bin/env python3
"""

Install
  pip install opencv-python numpy pillow

Usage
  python remove_logo_image.py photo.png                    # -> photo_clean.png
  python remove_logo_image.py photo.png -o out.png
  python remove_logo_image.py ./folder -o ./cleaned        # whole folder
  python remove_logo_image.py photo.png --preview          # zoomed before/after

  If Google ever changes the logo, learn a new alpha map from a few
  watermarked Gemini images of the same size, then use it:
  python remove_logo_image.py --learn ./some_gemini_images --save-alpha my_alpha.png
  python remove_logo_image.py photo.png --alpha my_alpha.png

Alpha maps: from py-gemini-watermark-remover (MIT License,
Copyright (c) 2025 py-gemini-watermark-remover contributors).
"""
import argparse
import base64
import os
import sys

import cv2
import numpy as np
from PIL import Image

ALPHA_48_B64 = ""
ALPHA_96_B64 = ""

EXTS = {".png", ".jpg", ".jpeg", ".webp", ".bmp", ".tif", ".tiff"}
MIN_ALPHA = 0.002          # below this the logo has no visible effect -> pixel untouched
MAX_ALPHA = 0.99


# ------------------------------------------------------------------ alpha maps

def load_builtin(b64):
    buf = np.frombuffer(base64.b64decode(b64), np.uint8)
    img = cv2.imdecode(buf, cv2.IMREAD_COLOR)
    return img.max(axis=2).astype(np.float32) / 255.0     # captured on black: alpha = max(RGB)/255


def load_alpha_file(path):
    img = cv2.imread(path, cv2.IMREAD_UNCHANGED)
    if img is None:
        sys.exit(f"Cannot read alpha map {path}")
    if img.ndim == 3:
        img = img[..., :3].max(axis=2)
    a = img.astype(np.float32)
    return a / (65535.0 if img.dtype == np.uint16 else 255.0)


# ------------------------------------------------------------------ locate

def expected_box(w, h):
    """Gemini's rule: 96px logo / 64px margin if both sides > 1024, else 48 / 32."""
    if w > 1024 and h > 1024:
        return 96, 64
    return 48, 32


def ncc(a, b):
    a = a - a.mean(); b = b - b.mean()
    d = np.sqrt((a * a).sum() * (b * b).sum())
    return float((a * b).sum() / d) if d > 1e-6 else 0.0


def locate(rgb, alphas, search_frac=0.35):
    """1) Check the exact spot Gemini uses. 2) Otherwise (resized/cropped image)
    search scales and positions with normalized cross-correlation.
    Returns (x, y, alpha_map_at_that_size, score, how)."""
    h, w = rgb.shape[:2]
    gray = cv2.cvtColor(rgb, cv2.COLOR_RGB2GRAY).astype(np.float32)

    size, margin = expected_box(w, h)
    native = {a.shape[0]: a for a in alphas}
    a0 = native.get(size)
    if a0 is None:
        a0 = cv2.resize(alphas[0], (size, size), interpolation=cv2.INTER_AREA)
    best = (None, None, None, -1.0, "")
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            x, y = w - size - margin + dx, h - size - margin + dy
            if x < 0 or y < 0:
                continue
            sc = ncc(gray[y:y + size, x:x + size], a0)
            if sc > best[3]:
                best = (x, y, a0, sc, "standard position")
    if best[3] >= 0.35:
        return best

    # search: coarse scales, then refine around the best size
    sx0, sy0 = int(w * (1 - search_frac)), int(h * (1 - search_frac))
    region = gray[sy0:, sx0:]
    base = max(alphas, key=lambda a: a.shape[0])

    def try_size(sz):
        if sz < 16 or sz >= min(region.shape) - 2:
            return None
        a = cv2.resize(base, (sz, sz), interpolation=cv2.INTER_AREA)
        res = cv2.matchTemplate(region, a, cv2.TM_CCOEFF_NORMED)
        _, mx, _, loc = cv2.minMaxLoc(res)
        return (sx0 + loc[0], sy0 + loc[1], a, float(mx), "searched")

    cands = [r for r in (try_size(int(round(size * f))) for f in np.geomspace(0.4, 2.5, 30)) if r]
    if not cands:
        return best
    top = max(cands, key=lambda r: r[3])
    s0 = top[2].shape[0]
    fine = [r for r in (try_size(z) for z in range(int(s0 * 0.9), int(s0 * 1.1) + 2)) if r]
    top = max(fine + [top], key=lambda r: r[3])
    return top if top[3] > best[3] else best


# ------------------------------------------------------------------ restore

def unblend(region, a, logo=255.0):
    A = np.minimum(a, MAX_ALPHA)[..., None]
    out = (region.astype(np.float32) - A * logo) / (1.0 - A)
    keep = (a < MIN_ALPHA)[..., None]
    out = np.where(keep, region.astype(np.float32), out)
    return np.clip(np.rint(out), 0, 255).astype(np.uint8)


def residual(restored, a):
    """How much of the logo shape is still visible (lower is better)."""
    g = cv2.cvtColor(restored, cv2.COLOR_RGB2GRAY).astype(np.float32)
    a = a.astype(np.float32)
    m = a > 0.02
    if m.sum() < 10:
        return 0.0
    gx, gy = cv2.Sobel(g, cv2.CV_32F, 1, 0), cv2.Sobel(g, cv2.CV_32F, 0, 1)
    ax, ay = cv2.Sobel(a, cv2.CV_32F, 1, 0), cv2.Sobel(a, cv2.CV_32F, 0, 1)
    # projection of image gradients onto the logo's own edges
    edge = np.abs((gx * ax + gy * ay)[m]).mean() / (np.hypot(ax, ay)[m].mean() + 1e-6)
    c = np.corrcoef(g[m], a[m])[0, 1] if g[m].std() > 1e-3 else 0.0
    return edge + 40 * abs(c)


def fit_and_restore(rgb, x, y, a):
    """Try nearby positions and strengths; keep the one that leaves no trace."""
    h, w = rgb.shape[:2]
    ah, aw = a.shape
    best = None
    for dy in (-1, 0, 1):
        for dx in (-1, 0, 1):
            xx, yy = x + dx, y + dy
            if xx < 0 or yy < 0 or xx + aw > w or yy + ah > h:
                continue
            reg = rgb[yy:yy + ah, xx:xx + aw]
            for k in np.arange(0.70, 1.31, 0.03):
                ak = np.clip(a * np.float32(k), 0, MAX_ALPHA).astype(np.float32)
                r = unblend(reg, ak)
                s = residual(r, ak)
                if best is None or s < best[0]:
                    best = (s, xx, yy, k, r)
    return best


# ------------------------------------------------------------------ learn

def learn_alpha(folder, size=None):
    """Least-squares alpha estimate from several watermarked images (same idea as
    the video tool: guess the background by inpainting, solve for alpha)."""
    files = [os.path.join(folder, f) for f in sorted(os.listdir(folder))
             if os.path.splitext(f)[1].lower() in EXTS]
    imgs = [np.array(Image.open(f).convert("RGB")) for f in files]
    if len(imgs) < 3:
        sys.exit("Need at least 3 watermarked images to learn from.")
    w, h = imgs[0].shape[1], imgs[0].shape[0]
    size = size or expected_box(w, h)[0]
    margin = size * 2 // 3
    num = den = 0
    used = 0
    for im in imgs:
        H, W = im.shape[:2]
        pad = size // 2
        x0, y0 = W - size - margin - pad, H - size - margin - pad
        crop = im[max(y0, 0):H - margin + pad, max(x0, 0):W - margin + pad]
        hole = np.zeros(crop.shape[:2], np.uint8)
        hole[pad:pad + size, pad:pad + size] = 255
        bg = cv2.inpaint(crop, hole, 5, cv2.INPAINT_TELEA).astype(np.float32)
        I = crop.astype(np.float32)
        d = 255.0 - bg
        n_ = ((I - bg) * d).sum(axis=2)[pad:pad + size, pad:pad + size]
        d_ = (d * d).sum(axis=2)[pad:pad + size, pad:pad + size]
        num, den, used = num + n_, den + d_, used + 1
    a = np.clip(num / np.maximum(den, 1e-3), 0, MAX_ALPHA)
    a[a < 0.01] = 0
    print(f"Learned a {size}x{size} alpha map from {used} images (max opacity {a.max():.2f})")
    return a


# ------------------------------------------------------------------ io

def save_like(src_path, pil_src, arr, out_path):
    ext = os.path.splitext(out_path)[1].lower()
    mode = pil_src.mode
    out = Image.fromarray(arr, "RGBA" if arr.shape[2] == 4 else "RGB")
    if mode in ("L", "P") and arr.shape[2] == 3:
        out = out.convert("RGB")
    kw = {}
    if "icc_profile" in pil_src.info:
        kw["icc_profile"] = pil_src.info["icc_profile"]
    exif = pil_src.info.get("exif")
    if exif:
        kw["exif"] = exif
    if ext in (".jpg", ".jpeg"):
        out.convert("RGB").save(out_path, quality=100, subsampling=0, **kw)
    elif ext == ".webp":
        out.save(out_path, lossless=True, exact=True, **kw)
    elif ext == ".png":
        from PIL import PngImagePlugin
        info = PngImagePlugin.PngInfo()
        for k, v in pil_src.info.items():
            if isinstance(v, str):
                info.add_text(k, v)
        out.save(out_path, pnginfo=info, compress_level=6, **kw)
    else:
        out.save(out_path, **kw)


def default_out(path, out_dir=None):
    base, ext = os.path.splitext(os.path.basename(path))
    if ext.lower() in (".jpg", ".jpeg"):
        ext = ".png"            # PNG keeps every pixel exact; JPEG would re-compress the whole image
    name = base + "_clean" + ext
    return os.path.join(out_dir or os.path.dirname(path) or ".", name)


# ------------------------------------------------------------------ main

def process(path, out_path, alphas, args):
    pil = Image.open(path)
    pil.load()
    has_alpha = pil.mode in ("RGBA", "LA") or (pil.mode == "P" and "transparency" in pil.info)
    full = np.array(pil.convert("RGBA" if has_alpha else "RGB"))
    rgb = full[..., :3]
    h, w = rgb.shape[:2]

    x, y, a, score, how = locate(rgb, alphas)
    if a is None or score < args.min_score:
        print(f"  {os.path.basename(path)}: no Gemini watermark found (match {score:.2f}) - skipped")
        return False
    ah, aw = a.shape
    if args.fit_strength:
        _, x, y, k, restored = fit_and_restore(rgb, x, y, a)
    else:
        k = 1.0
        restored = unblend(rgb[y:y + ah, x:x + aw], a)

    if args.preview:
        pad = max(aw // 2, 8)
        X0, Y0 = max(x - pad, 0), max(y - pad, 0)
        X1, Y1 = min(x + aw + pad, w), min(y + ah + pad, h)
        after = rgb.copy()
        after[y:y + ah, x:x + aw] = restored
        z = lambda im: cv2.resize(im[Y0:Y1, X0:X1], None, fx=6, fy=6, interpolation=cv2.INTER_NEAREST)
        pv = np.hstack([z(rgb), np.full((z(rgb).shape[0], 6, 3), 255, np.uint8), z(after)])
        pv_path = os.path.splitext(out_path)[0] + "_preview.png"
        Image.fromarray(pv).save(pv_path)
        print(f"  preview -> {pv_path}  (left: original, right: cleaned, 6x zoom)")
        return True

    result = full.copy()
    result[y:y + ah, x:x + aw, :3] = restored
    save_like(path, pil, result, out_path)

    # verify: everything outside the watermark box must be identical
    check = np.array(Image.open(out_path).convert("RGBA" if has_alpha else "RGB"))
    outside = np.ones((h, w), bool)
    outside[y:y + ah, x:x + aw] = False
    diff = int((check[outside] != full[outside]).any(axis=-1).sum())
    lossless = diff == 0
    note = "all other pixels identical" if lossless else \
        f"{diff} pixels outside changed (JPEG re-compression; save as .png to avoid)"
    print(f"  {os.path.basename(path)} -> {out_path}\n"
          f"    logo {aw}x{ah} at ({x},{y}) [{how}], match {score:.2f}; {note}")
    return True


def main():
    p = argparse.ArgumentParser(description="Remove the Gemini watermark from images losslessly.")
    p.add_argument("input", nargs="?", help="image file or folder")
    p.add_argument("-o", "--output", help="output file, or folder when input is a folder")
    p.add_argument("--alpha", help="custom alpha map image (white = opaque logo)")
    p.add_argument("--preview", action="store_true", help="save a zoomed before/after and exit")
    p.add_argument("--min-score", type=float, default=0.25,
                   help="minimum template match to treat as watermark (default 0.25)")
    p.add_argument("--fit-strength", action="store_true",
                   help="also search watermark strength (only if a faint outline remains)")
    p.add_argument("--learn", metavar="FOLDER", help="learn an alpha map from watermarked images")
    p.add_argument("--save-alpha", default="learned_alpha.png", help="where --learn saves the map")
    args = p.parse_args()

    if args.learn:
        a = learn_alpha(args.learn)
        cv2.imwrite(args.save_alpha, np.rint(a * 255).astype(np.uint8))
        print(f"Saved -> {args.save_alpha}   use it with --alpha {args.save_alpha}")
        return
    if not args.input:
        p.error("give an image or folder")

    alphas = [load_alpha_file(args.alpha)] if args.alpha else \
        [load_builtin(ALPHA_96_B64), load_builtin(ALPHA_48_B64)]

    if os.path.isdir(args.input):
        out_dir = args.output or os.path.join(args.input, "cleaned")
        os.makedirs(out_dir, exist_ok=True)
        files = [f for f in sorted(os.listdir(args.input)) if os.path.splitext(f)[1].lower() in EXTS]
        done = 0
        for f in files:
            src = os.path.join(args.input, f)
            done += process(src, default_out(src, out_dir), alphas, args)
        print(f"Done: {done}/{len(files)} images cleaned -> {out_dir}")
    else:
        if not os.path.isfile(args.input):
            sys.exit(f"Not found: {args.input}")
        out = args.output or default_out(args.input)
        process(args.input, out, alphas, args)


if __name__ == "__main__":
    main()